#include <stdio.h>

struct Cat {
    char name[20];
    int fish;
};

int main(void) {
    struct Cat a = {"{who}", {f1}};
    struct Cat *p = &a;

    p->fish = {f2};
    printf("%s 吃了 %d 条喵\n", a.name, a.fish);
    return 0;
}
